/* @autogenerated */
package net.civeira.phylax.feature.observe.metric;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;

import org.eclipse.microprofile.config.inject.ConfigProperty;

import io.opentelemetry.api.common.AttributeKey;
import io.opentelemetry.api.trace.SpanKind;
import io.opentelemetry.api.trace.StatusCode;
import io.opentelemetry.sdk.trace.data.SpanData;
import jakarta.enterprise.context.ApplicationScoped;
import lombok.extern.slf4j.Slf4j;
import net.civeira.phylax.feature.observe.store.TelemetryStore;

/**
 * RED metrics of the sources: counts the server spans before the sampling (from the exporter),
 * stores the closed minutes and hours every minute and answers the queries of the viewer.
 *
 * <ul>
 * <li>Up to 6 hours: points of one minute; up to 24 hours: of five minutes (from the minute
 * points); beyond: of one hour (the rollup, plus the minute points of the hours not rolled up
 * yet).</li>
 * <li>Percentiles from the fixed buckets of {@link Histogram}.</li>
 * </ul>
 */
@ApplicationScoped
@Slf4j
public class ObserveMetrics {

  private static final AttributeKey<String> ROUTE = AttributeKey.stringKey("http.route");
  private static final AttributeKey<String> METHOD = AttributeKey.stringKey("http.request.method");
  private static final AttributeKey<String> METHOD_OLD = AttributeKey.stringKey("http.method");
  private static final AttributeKey<Long> STATUS =
      AttributeKey.longKey("http.response.status_code");
  private static final AttributeKey<Long> STATUS_OLD = AttributeKey.longKey("http.status_code");
  private static final long SIX_HOURS = 6 * MetricDeriver.HOUR;
  private static final long DAY = 24 * MetricDeriver.HOUR;

  private final TelemetryStore store;
  private final MetricDeriver deriver;
  private final EdgeDeriver edges;
  private static final AttributeKey<String> DB_SYSTEM = AttributeKey.stringKey("db.system");
  private static final AttributeKey<String> DB_NAME = AttributeKey.stringKey("db.namespace");
  private static final AttributeKey<String> DB_NAME_OLD = AttributeKey.stringKey("db.name");
  private static final AttributeKey<String> MESSAGING = AttributeKey.stringKey("messaging.system");
  private static final AttributeKey<String> PEER = AttributeKey.stringKey("peer.service");
  private static final AttributeKey<String> SERVER = AttributeKey.stringKey("server.address");
  private static final AttributeKey<String> SERVER_OLD = AttributeKey.stringKey("net.peer.name");

  public ObserveMetrics(final TelemetryStore store,
      final @ConfigProperty(name = "app.observe.metrics.max-series",
          defaultValue = "2000") int maxSeries) {
    this.store = store;
    this.deriver = new MetricDeriver(maxSeries);
    this.edges = new EdgeDeriver(deriver);
  }

  /**
   * Counts a span of a source, whatever its sampling: SERVER and CONSUMER are its requests, CLIENT
   * and PRODUCER its calls (the edges of the service map).
   */
  public void record(final String source, final SpanData span) {
    if (span.getKind() == SpanKind.CLIENT || span.getKind() == SpanKind.PRODUCER) {
      recordCall(source, span);
      return;
    }
    if (span.getKind() != SpanKind.SERVER && span.getKind() != SpanKind.CONSUMER) {
      return;
    }
    edges.server(source, parentId(span));
    String route = span.getAttributes().get(ROUTE);
    String method = span.getAttributes().get(METHOD);
    if (null == method) {
      method = span.getAttributes().get(METHOD_OLD);
    }
    Long status = span.getAttributes().get(STATUS);
    if (null == status) {
      status = span.getAttributes().get(STATUS_OLD);
    }
    boolean error =
        span.getStatus().getStatusCode() == StatusCode.ERROR || (null != status && status >= 500);
    long start = span.getStartEpochNanos() / 1_000_000;
    double millis = (span.getEndEpochNanos() - span.getStartEpochNanos()) / 1_000_000.0;
    deriver.record(source, null == route ? span.getName() : route, method, start, millis, error);
  }

  private void recordCall(final String source, final SpanData span) {
    var attrs = span.getAttributes();
    String db = attrs.get(DB_SYSTEM);
    String database = null;
    if (null != db) {
      String name = null != attrs.get(DB_NAME) ? attrs.get(DB_NAME) : attrs.get(DB_NAME_OLD);
      database = "db:" + db + (null == name ? "" : "/" + name);
    }
    String external = null != attrs.get(MESSAGING) ? "mq:" + attrs.get(MESSAGING)
        : null != attrs.get(PEER) ? attrs.get(PEER)
            : null != attrs.get(SERVER) ? attrs.get(SERVER) : attrs.get(SERVER_OLD);
    long start = span.getStartEpochNanos() / 1_000_000;
    double millis = (span.getEndEpochNanos() - span.getStartEpochNanos()) / 1_000_000.0;
    Long status = span.getAttributes().get(STATUS);
    boolean error =
        span.getStatus().getStatusCode() == StatusCode.ERROR || (null != status && status >= 500);
    edges.client(source, span.getSpanId(), start, millis, error, database, external,
        System.currentTimeMillis());
  }

  private static String parentId(final SpanData span) {
    var context = span.getParentSpanContext();
    if (null != context) {
      return context.isValid() ? context.getSpanId() : null;
    }
    String id = span.getParentSpanId();
    return null == id || id.chars().allMatch(c -> c == '0') ? null : id;
  }

  /**
   * The service map of the range: edges (from, to, requests, rpm, error rate, p95) of the points of
   * method CLIENT, and the nodes they join.
   */
  public Map<String, Object> map(final Set<String> sources, final long from, final long to) {
    long range = to - from;
    List<MetricPoint> points = raw(sources, from, to, range > DAY).stream()
        .filter(point -> MetricDeriver.CLIENT.equals(point.method())).toList();
    List<Map<String, Object>> edgeRows = new ArrayList<>();
    for (Map<String, Object> row : routes(points, Math.max(1, range / MetricDeriver.MINUTE))) {
      String target = String.valueOf(row.get("route"));
      row.put("from", row.remove("src"));
      row.put("to",
          target.startsWith(EdgeDeriver.ARROW) ? target.substring(EdgeDeriver.ARROW.length())
              : target);
      row.remove("route");
      row.remove("method");
      edgeRows.add(row);
    }
    Map<String, Object> result = new LinkedHashMap<>();
    result.put("edges", edgeRows);
    return result;
  }

  private static final com.fasterxml.jackson.databind.ObjectMapper JSON =
      new com.fasterxml.jackson.databind.ObjectMapper();
  private static final java.util.regex.Pattern ID_SEGMENT = java.util.regex.Pattern.compile(
      "/(?:\\d+|[0-9a-fA-F]{8}-[0-9a-fA-F-]{27,}|[0-9a-fA-F]{16,}|[A-Za-z0-9_-]{24,})(?=/|$)");

  /**
   * A Web Vital of a front (log {@code web-vital} of the Angular SDK, its value in
   * {@code log.args}): counted as method VITAL, route "<name> <page>", the value in ms (CLS ×
   * 1000), "poor" as error.
   */
  public void recordVital(final net.civeira.phylax.feature.observe.store.ObsLog log) {
    if (!"web-vital".equals(log.msg()) || null == log.attrs()
        || null == log.attrs().get("log.args")) {
      return;
    }
    try {
      var args = JSON.readTree(String.valueOf(log.attrs().get("log.args")));
      var vital = args.isArray() ? args.path(0) : args;
      String name = vital.path("name").asText("");
      if (name.isEmpty() || !vital.has("value")) {
        return;
      }
      double value = vital.path("value").asDouble();
      deriver.record(log.src(), name + " " + page(vital.path("route").asText("/")),
          MetricDeriver.VITAL, log.ts(), "CLS".equals(name) ? value * 1000 : value,
          "poor".equals(vital.path("rating").asText()));
    } catch (java.io.IOException | RuntimeException ex) {
      // Not a vital of the SDK: ignored
    }
  }

  /** Path of a page without query, hash nor ids (numbers, UUIDs, long tokens become :id). */
  static String page(final String route) {
    String path = null == route ? "/" : route.replaceFirst("[?#].*$", "");
    String result = ID_SEGMENT.matcher(path).replaceAll("/:id");
    return result.length() > 120 ? result.substring(0, 120) : result;
  }

  /** Web Vitals of the range: p75 (the threshold of web.dev), samples and share of poor values. */
  public List<Map<String, Object>> vitals(final Set<String> sources, final long from,
      final long to) {
    Map<String, Acc> byKey = new LinkedHashMap<>();
    Map<String, String[]> keys = new LinkedHashMap<>();
    for (MetricPoint point : raw(sources, from, to, to - from > DAY)) {
      if (!MetricDeriver.VITAL.equals(point.method())) {
        continue;
      }
      String key = point.src() + "\n" + point.route();
      byKey.computeIfAbsent(key, k -> new Acc()).add(point);
      int space = point.route().indexOf(' ');
      keys.putIfAbsent(key,
          new String[] {point.src(), space < 0 ? point.route() : point.route().substring(0, space),
              space < 0 ? "" : point.route().substring(space + 1)});
    }
    List<Map<String, Object>> rows = new ArrayList<>();
    byKey.forEach((key, acc) -> {
      String[] parts = keys.get(key);
      Double p75 = acc.histogram.percentile(0.75);
      Map<String, Object> row = new LinkedHashMap<>();
      row.put("src", parts[0]);
      row.put("name", parts[1]);
      row.put("page", parts[2]);
      row.put("samples", acc.count);
      row.put("p75", null == p75 ? null
          : "CLS".equals(parts[1]) ? Math.round(p75) / 1000.0 : (double) Math.round(p75));
      row.put("poorRate", acc.count == 0 ? 0 : Math.round(1000.0 * acc.errors / acc.count) / 10.0);
      rows.add(row);
    });
    rows.sort(Comparator.comparing((Map<String, Object> row) -> String.valueOf(row.get("page")))
        .thenComparing(row -> String.valueOf(row.get("name"))));
    return rows;
  }

  /** A check of a probe, as a request of method PROBE and route "probe <name>" of its source. */
  public void recordProbe(final String source, final String name, final long ts,
      final long latencyMs, final boolean failed) {
    deriver.record(source, "probe " + name, MetricDeriver.PROBE, ts, latencyMs, failed);
  }

  /** Every minute: the closed minutes and hours go to the store. */
  public void flush() {
    edges.sweep(System.currentTimeMillis());
    MetricDeriver.Drained drained = deriver.drain(System.currentTimeMillis());
    List<MetricPoint> points = new ArrayList<>(drained.minutes());
    points.addAll(drained.hours());
    if (!points.isEmpty()) {
      store.appendPoints(points);
    }
  }

  /**
   * Series and routes of the range for the viewer.
   *
   * @param route only this route; empty for all
   */
  public Map<String, Object> query(final Set<String> sources, final String route, final long from,
      final long to) {
    long range = to - from;
    long step = range <= SIX_HOURS ? MetricDeriver.MINUTE
        : range <= DAY ? 5 * MetricDeriver.MINUTE : MetricDeriver.HOUR;
    List<MetricPoint> points = raw(sources, from, to, step >= MetricDeriver.HOUR).stream()
        .filter(point -> !MetricDeriver.special(point.method())).toList();
    List<MetricPoint> selected = points.stream()
        .filter(p -> null == route || route.isBlank() || route.equals(p.route())).toList();
    Map<String, Object> result = new LinkedHashMap<>();
    result.put("step", step);
    result.put("series", series(selected, from, step));
    result.put("routes", routes(points, Math.max(1, range / MetricDeriver.MINUTE)));
    return result;
  }

  /**
   * The points of the range: with {@code hourly}, the rollup where it exists and the minutes of the
   * hours not rolled up yet; otherwise the minutes. Plus the minutes not drained yet.
   */
  public List<MetricPoint> raw(final Set<String> sources, final long from, final long to,
      final boolean hourly) {
    List<MetricPoint> points = new ArrayList<>();
    if (!hourly) {
      points.addAll(store.points(from, to, MetricDeriver.MINUTE, sources));
    } else {
      List<MetricPoint> hours = store.points(from, to, MetricDeriver.HOUR, sources);
      long rolledUntil =
          hours.stream().mapToLong(p -> p.ts() + MetricDeriver.HOUR).max().orElse(from);
      points.addAll(hours);
      points.addAll(store.points(Math.max(from, rolledUntil), to, MetricDeriver.MINUTE, sources));
    }
    for (MetricPoint open : deriver.open()) {
      if (open.ts() >= from && open.ts() < to
          && (sources.isEmpty() || sources.contains(open.src()))) {
        points.add(open);
      }
    }
    return points;
  }

  /** One point per interval of {@code step}: rate, error rate and latency percentiles. */
  static List<Map<String, Object>> series(final List<MetricPoint> points, final long from,
      final long step) {
    Map<Long, Acc> byTs = new TreeMap<>();
    for (MetricPoint point : points) {
      long ts = from + (point.ts() - from) / step * step;
      byTs.computeIfAbsent(ts, k -> new Acc()).add(point);
    }
    List<Map<String, Object>> result = new ArrayList<>();
    byTs.forEach((ts, acc) -> result.add(acc.toMap(ts, step / (double) MetricDeriver.MINUTE)));
    return result;
  }

  /** Totals of each route of the range, by requests. */
  static List<Map<String, Object>> routes(final List<MetricPoint> points, final long minutes) {
    Map<String, Acc> byRoute = new LinkedHashMap<>();
    Map<String, String[]> keys = new LinkedHashMap<>();
    for (MetricPoint point : points) {
      String key = point.src() + "\n" + point.method() + "\n" + point.route();
      byRoute.computeIfAbsent(key, k -> new Acc()).add(point);
      keys.putIfAbsent(key, new String[] {point.src(), point.method(), point.route()});
    }
    List<Map<String, Object>> result = new ArrayList<>();
    byRoute.forEach((key, acc) -> {
      Map<String, Object> row = acc.toMap(null, minutes);
      String[] parts = keys.get(key);
      row.put("src", parts[0]);
      row.put("method", parts[1]);
      row.put("route", parts[2]);
      result.add(row);
    });
    result.sort(Comparator.comparingLong((Map<String, Object> row) -> (Long) row.get("requests"))
        .reversed());
    return result.size() > 100 ? result.subList(0, 100) : result;
  }

  /** Sum of points. */
  static final class Acc {
    long count;
    long errors;
    double sumMs;
    final Histogram histogram = new Histogram();

    void add(final MetricPoint point) {
      count += point.count();
      errors += point.errors();
      sumMs += point.sumMs();
      histogram.merge(point.buckets());
    }

    Map<String, Object> toMap(final Long ts, final double minutes) {
      Map<String, Object> row = new LinkedHashMap<>();
      if (null != ts) {
        row.put("ts", ts);
      }
      row.put("requests", count);
      row.put("errors", errors);
      row.put("rpm", round(count / Math.max(minutes, 1e-9)));
      row.put("errorRate", count == 0 ? 0 : round(100.0 * errors / count));
      row.put("avg", count == 0 ? null : round(sumMs / count));
      row.put("totalMs", round(sumMs));
      row.put("p50", round(histogram.percentile(0.50)));
      row.put("p95", round(histogram.percentile(0.95)));
      row.put("p99", round(histogram.percentile(0.99)));
      return row;
    }

    private static Double round(final Double value) {
      return null == value ? null : Math.round(value * 10) / 10.0;
    }
  }
}
